function createAsyncTtlCache(ttlMs, now = () => Date.now()) {
  if (!Number.isFinite(ttlMs) || ttlMs < 0) {
    throw new RangeError("ttlMs must be a non-negative finite number");
  }
  const entries = new Map();

  function getOrLoad(key, loader) {
    const cached = entries.get(key);
    if (cached && (cached.expiresAt === null || cached.expiresAt > now())) {
      return cached.promise;
    }
    if (cached) entries.delete(key);

    const entry = { promise: undefined, expiresAt: null };
    entry.promise = Promise.resolve().then(loader);
    entries.set(key, entry);

    entry.promise.then(
      () => {
        if (entries.get(key) === entry) entry.expiresAt = now() + ttlMs;
      },
      () => {
        if (entries.get(key) === entry) entries.delete(key);
      },
    );
    return entry.promise;
  }

  return {
    getOrLoad,
    invalidate(key) { entries.delete(key); },
    clear() { entries.clear(); },
  };
}

const cache = createAsyncTtlCache(5_000);
const getProfile = (userId, locale) => cache.getOrLoad(
  `${userId}:${locale}`,
  async () => {
    const response = await fetch(`/api/users/${userId}?locale=${locale}`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.json();
  },
);

